					case 46: rsu = inputSampleR;
					case 47: rsv = inputSampleR;
					case 48: rsw = inputSampleR;
					case 49: rsx = inputSampleR;
					case 50: rsy = inputSampleR;
					case 51: rsz = inputSampleR;
